body.script:

(function() {
  var iframe = document.getElementById('mainFrame');
  var loadingScreen = document.getElementById('loadingScreen');
  var loadStatus = document.getElementById('loadStatus');

  // Plak hier de gewenste Base64-string van je HTML-pagina tussen de aanhalingstekens
  var base64Data = "";

  try {
    loadStatus.textContent = 'Base64 decoderen...';

    // Decodeer Base64 naar HTML (met ondersteuning voor UTF-8)
    var decodedHtml = decodeURIComponent(escape(atob(base64Data)));

    loadStatus.textContent = 'GameHub laden in iframe...';

    // Schrijf naar iframe
    var doc = iframe.contentDocument || iframe.contentWindow.document;
    doc.open();
    doc.write(decodedHtml);
    doc.close();

    loadStatus.textContent = '✅ GameHub geladen!';

    // Verberg laadscherm
    setTimeout(function() {
      loadingScreen.style.opacity = '0';
      setTimeout(function() {
        loadingScreen.style.display = 'none';
      }, 500);
    }, 300);

  } catch (error) {
    loadStatus.textContent = '❌ Fout bij laden: ' + error.message;
    loadStatus.style.color = '#ef4444';
    console.error('Fout bij verwerken Base64:', error);
  }
})();
